draw:
var E1 = p.emf1, E2 = p.emf2, R = p.res;
var I = (E1 - E2) / R;

var pad = Math.min(W, H) * 0.16;
var x0 = pad, x1 = W - pad, y0 = pad, y1 = H - pad * 0.9;

ctx.lineWidth = 2;
ctx.strokeStyle = C.rule;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// the loop, drawn as four sides with gaps for the components
// top side: battery 1 (gap in the middle)
var midT = (x0 + x1) / 2;
ctx.beginPath();
ctx.moveTo(x0, y0); ctx.lineTo(midT - 14, y0);
ctx.moveTo(midT + 14, y0); ctx.lineTo(x1, y0);
ctx.stroke();

// right side: resistor zigzag in the middle
var midR = (y0 + y1) / 2;
ctx.beginPath();
ctx.moveTo(x1, y0); ctx.lineTo(x1, midR - 24);
ctx.moveTo(x1, midR + 24); ctx.lineTo(x1, y1);
ctx.stroke();

// bottom side: battery 2 (gap in the middle)
ctx.beginPath();
ctx.moveTo(x1, y1); ctx.lineTo(midT + 14, y1);
ctx.moveTo(midT - 14, y1); ctx.lineTo(x0, y1);
ctx.stroke();

// left side: plain wire
ctx.beginPath();
ctx.moveTo(x0, y1); ctx.lineTo(x0, y0);
ctx.stroke();

// battery symbol helper (horizontal), plus plate on the +x side
function battH(cx, cy, flip) {
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx - 5 * flip, cy - 11); ctx.lineTo(cx - 5 * flip, cy + 11);
  ctx.stroke();
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(cx + 5 * flip, cy - 6); ctx.lineTo(cx + 5 * flip, cy + 6);
  ctx.stroke();
  ctx.lineWidth = 2;
}

// battery 1 on top: long (positive) plate on the left, so it drives current
// anticlockwise round the picture, i.e. down the left wire
battH(midT, y0, -1);
ctx.fillStyle = C.ink;
ctx.fillText("E1 = " + E1.toFixed(1) + " V", midT, y0 - 14);

// battery 2 on the bottom, opposing
battH(midT, y1, 1);
ctx.fillText("E2 = " + E2.toFixed(1) + " V", midT, y1 + 22);

// resistor on the right
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x1, midR - 24);
var k;
for (k = 0; k < 6; k++) {
  ctx.lineTo(x1 + (k % 2 === 0 ? 9 : -9), midR - 24 + 8 * (k + 0.5));
}
ctx.lineTo(x1, midR + 24);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("R = " + R.toFixed(1) + " ohm", x1 + 14, midR + 4);
ctx.textAlign = "center";

// moving charge dots: anticlockwise when I is positive
var per = Math.max(0.12, Math.abs(I)) * 0.5;
var phase = (t * per) % 1;
var dir = I >= 0 ? 1 : -1;
var Lx = x1 - x0, Ly = y1 - y0;
var per2 = 2 * (Lx + Ly);
var n;
ctx.fillStyle = C.accent;
for (n = 0; n < 12; n++) {
  var s = (((n / 12 + dir * phase) % 1) + 1) % 1;
  var d = s * per2;
  var px, py;
  if (d < Ly) { px = x0; py = y0 + d; }
  else if (d < Ly + Lx) { px = x0 + (d - Ly); py = y1; }
  else if (d < 2 * Ly + Lx) { px = x1; py = y1 - (d - Ly - Lx); }
  else { px = x1 - (d - 2 * Ly - Lx); py = y0; }
  ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI * 2); ctx.fill();
}

// loop-walk arrow in the middle
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(W / 2, (y0 + y1) / 2, Math.min(Lx, Ly) * 0.22, 0.4, 5.2);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("walk this way", W / 2, (y0 + y1) / 2 + 4);

out.note = "I = (" + E1.toFixed(1) + " - " + E2.toFixed(1) + ") / " + R.toFixed(1) +
  " = " + I.toFixed(3) + " A" + (I < 0 ? "  (runs the other way)" : "") +
  ",  drop across R = " + (I * R).toFixed(2) + " V";
